import { test, expect, setThemeQuotaGating } from "../helpers/theme-browser";
import AxeBuilder from "@axe-core/playwright";
import type { QuotaSnapshot } from "../../src/lib/quota-snapshot";
import { PLANS } from "../../src/lib/plans";

test("History allowance: plans, four themes, responsive meters and keyboard access", async ({
  page,
}, testInfo) => {
  test.setTimeout(120000);
  await setThemeQuotaGating(true);
  await page.emulateMedia({ reducedMotion: "reduce" });
  await page.goto("/history");
  const response = await page.request.get("/api/quota");
  const original: QuotaSnapshot = await response.json();
  if (original.mode !== "gated") throw new Error("Gated fixture required");
  let current = { ...original, sendingAllowed: true };
  await page.route("**/api/quota", (route) => route.fulfill({ json: current }));
  const pill = page.getByRole("region", { name: "Email allowances" });
  const daily = pill.getByRole("meter", { name: "Daily emails left" });
  const monthly = pill.getByRole("meter", { name: "Monthly emails left" });
  const action = pill.getByRole("link", { name: "View allowances" });
  async function refresh() {
    await page.evaluate(() =>
      window.dispatchEvent(new Event("focus")),
    );
  }
  for (const plan of ["FREE", "PAID"] as const) {
    const dailyRemaining = plan === "FREE" ? 3 : 17;
    const monthlyRemaining = plan === "FREE" ? 14 : 241;
    current = {
      ...current,
      plan,
      daily: {
        ...current.daily,
        limit: PLANS[plan].dailyEmails,
        remaining: dailyRemaining,
      },
      monthly: {
        ...current.monthly,
        limit: PLANS[plan].monthlyEmails,
        remaining: monthlyRemaining,
        startsAt: "2026-11-01T00:00:00Z",
      },
    };
    // History streams before the quota provider has necessarily hydrated.
    await expect
      .poll(async () => {
        await refresh();
        return (await daily.count())
          ? daily.getAttribute("aria-valuenow")
          : null;
      })
      .toBe(String(dailyRemaining));
    await expect(monthly).toHaveAttribute(
      "aria-valuenow",
      String(monthlyRemaining),
    );
    await expect(daily).toHaveAttribute(
      "aria-valuemax",
      String(PLANS[plan].dailyEmails),
    );
    await expect(monthly).toHaveAttribute(
      "aria-valuemax",
      String(PLANS[plan].monthlyEmails),
    );
    await expect(daily.locator("[data-filled=true]")).toHaveCount(
      plan === "FREE" ? 3 : 0,
    );
    for (const [appearance, theme, barHeight, surface] of [
      ["purple", "light", "5px", "rgb(255, 255, 255)"],
      ["purple", "dark", "5px", "rgb(14, 12, 29)"],
      ["vercel", "light", "4px", "rgb(255, 255, 255)"],
      ["vercel", "dark", "2px", "rgb(18, 18, 18)"],
    ]) {
      await page.evaluate(
        ({ appearance, theme }) => {
          document.documentElement.dataset.appearance = appearance;
          document.documentElement.dataset.theme = theme;
        },
        { appearance, theme },
      );
      await expect(pill).toHaveCSS("background-color", surface);
      await expect(monthly).toHaveCSS("height", barHeight);
      await expect(monthly).toHaveCSS("width", "56px");
      await expect(pill).toHaveCSS("font-family", /PlusJakartaSans/);
      await expect(action).toHaveCSS("background-image", "none");
      await expect(action).toHaveCSS("font-weight", "600");
      await expect(action.locator("svg")).toHaveAttribute("width", "14");
      for (const width of [320, 390, 640, 768, 1024, 1280]) {
        await page.setViewportSize({ width, height: 1000 });
        await expect(action).toBeVisible();
        const bounds = await pill.boundingBox();
        expect(bounds!.x).toBeGreaterThanOrEqual(0);
        expect(bounds!.x + bounds!.width).toBeLessThanOrEqual(width);
        expect(
          await page.evaluate(
            () => document.documentElement.scrollWidth <= innerWidth,
          ),
        ).toBe(true);
        const button = await action.boundingBox();
        expect(button!.height).toBeGreaterThanOrEqual(44);
        if (width >= 1024) expect(bounds!.height).toBe(56);
        if (width < 640) {
          const meter = await monthly.boundingBox();
          expect(button!.y).toBeGreaterThan(meter!.y + meter!.height);
          expect(button!.width).toBeGreaterThan(bounds!.width - 30);
        }
      }
      if (
        await page.evaluate(
          () => matchMedia("(hover: hover) and (pointer: fine)").matches,
        )
      ) {
        const restingBackground = await action.evaluate(
          (element) => getComputedStyle(element).backgroundColor,
        );
        await action.hover();
        await expect
          .poll(() =>
            action.evaluate(
              (element) => getComputedStyle(element).backgroundColor,
            ),
          )
          .not.toBe(restingBackground);
        const hoverAudit = await new AxeBuilder({ page })
          .include('[aria-label="Email allowances"]')
          .analyze();
        expect(hoverAudit.violations).toEqual([]);
        await pill.screenshot({
          path: testInfo.outputPath(`${plan}-${appearance}-${theme}-hover.png`),
        });
        await page.mouse.move(0, 0);
      }
      await action.focus();
      await expect(action).toHaveCSS("outline-style", "solid");
      const audit = await new AxeBuilder({ page })
        .include('[aria-label="Email allowances"]')
        .analyze();
      expect(audit.violations).toEqual([]);
      await pill.screenshot({
        path: testInfo.outputPath(`${plan}-${appearance}-${theme}.png`),
      });
      await page.setViewportSize({ width: 390, height: 1000 });
      const mobileAudit = await new AxeBuilder({ page })
        .include('[aria-label="Email allowances"]')
        .analyze();
      expect(mobileAudit.violations).toEqual([]);
      await pill.screenshot({
        path: testInfo.outputPath(`${plan}-${appearance}-${theme}-narrow.png`),
      });
    }
  }
  for (const remaining of [2, 0]) {
    current = { ...current, daily: { ...current.daily, remaining } };
    await refresh();
    await expect(daily).toHaveAttribute("aria-valuenow", String(remaining));
    const audit = await new AxeBuilder({ page })
      .include('[aria-label="Email allowances"]')
      .analyze();
    expect(audit.violations).toEqual([]);
  }
  await expect(action).toHaveAttribute("href", "/usage#allowances");
  await action.click();
  await expect(page).toHaveURL(/\/usage#allowances$/);
});
